head.script:
scwin.trigger1_onclick = function(e) {
    gridView1.setScrollLeft(0);
};
scwin.trigger2_onclick = function(e) {
    gridView1.setScrollTop(0);
};
scwin.trigger3_onclick = function(e) {
    gridView2.setScrollLeft(0);
};
scwin.trigger4_onclick = function(e) {
    gridView2.setScrollTop(0);
};
scwin.__scrollLeft = function(grid) {
    grid.setScrollLeft(950);
}
scwin.__scrollTop = function(grid) {
    grid.setScrollTop(500);
}
scwin.__isscrollLeft = function(grid) {
    return WebSquare.wUnit.getJq(grid + "_scrollX_right").scrollLeft() == 0;
}
scwin.__isscrollTop = function(grid) {
    return WebSquare.wUnit.getJq(grid + "_scrollY_div").scrollTop() == 0;
}
scwin.setVal = function() {
    scwin.__scrollLeft(gridView1);
}
scwin.setVal2 = function() {
    return scwin.__isscrollLeft('#gridView1');
}
scwin.setVal3 = function() {
    scwin.__scrollTop(gridView1);
}
scwin.setVal4 = function() {
    return scwin.__isscrollTop('#gridView1');
}
scwin.setVal5 = function() {
    scwin.__scrollLeft(gridView2);
}
scwin.setVal6 = function() {
    return scwin.__isscrollLeft('#gridView2');
}
scwin.setVal7 = function() {
    scwin.__scrollTop(gridView2);
}
scwin.setVal8 = function() {
    return scwin.__isscrollTop('#gridView2');
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 5. 브라우저에서 GridView1 의 가로스크롤을 오른쪽으로 이동하고 gridView1.setScrollLeft(0) 버튼을 클릭한다.
    //5. In the browser, move the horizontal scroll of GridView1 to the right and click the gridView1.setScrollLeft (0) button.
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 5. GridView1 의 가로스크롤이 오른쪽에서 왼쪽으로 초기화된다.
    //5. Horizontal scrolling of GridView1 is initialized from right to left. 
    WebSquare.wUnit.addCommand("assert", "scwin.setVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 6. GridView1 의 세로스크롤을 아래쪽으로 이동하고 gridView1.setScrollTop(0) 버튼을 클릭한다.
    //6. Move the vertical scroll of GridView1 to the bottom and click the gridView1.setScrollTop (0) button.
    WebSquare.wUnit.addCommand("set", "scwin.setVal3()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 6. GridView1 의 세로스크롤이 아래쪽에서 위쪽으로 초기화된다.
    //6. The vertical scroll of GridView1 is initialized from bottom to top.
    WebSquare.wUnit.addCommand("assert", "scwin.setVal4()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 7. GridView2 의 가로스크롤을 오른쪽으로 이동하고 gridView2.setScrollLeft(0) 버튼을 클릭한다.
    //7. Move the horizontal scroll of GridView2 to the right and click the gridView2.setScrollLeft (0) button.
    WebSquare.wUnit.addCommand("set", "scwin.setVal5()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 7. GridView2 의 가로스크롤이 오른쪽에서 왼쪽으로 초기화된다.
    //7. Horizontal scrolling of GridView2 is initialized from right to left.
    WebSquare.wUnit.addCommand("assert", "scwin.setVal6()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 8. GridView2 의 세로스크롤을 아래쪽으로 이동하고 gridView2.setScrollTop(0) 버튼을 클릭한다.
    //8. Move the vertical scroll of GridView2 down and click the gridView2.setScrollTop (0) button.
    WebSquare.wUnit.addCommand("set", "scwin.setVal7()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 8. GridView2 의 세로스크롤이 아래쪽에서 위쪽으로 초기화된다.
    //8. The vertical scroll of GridView2 is initialized from bottom to top.
    WebSquare.wUnit.addCommand("assert", "scwin.setVal8()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.data = [];
    for (var i = 0; i < 20; i++) {
        for (var j = 0; j < 10; j++) {
            data.push(i * 10 + j);
        }
    }
    dataList1.setData(data);
    //Function unitTest
    //Created By: Sang.do
    //Created By: 19-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
